'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='relais-tuteurs-v1', DEMO='relais-tuteurs-demo-v1';
const fresh=()=>({version:1,tutors:[],groups:[],tasks:[],entries:[]});
let data=fresh(),demo=false,view='journal',toastTimer;
let revision=window.RELAIS_BOOT?.revision??0, currentUser=window.RELAIS_BOOT?.user||null;
const shared=!!window.RELAIS_BOOT;
const isAdmin=()=>!shared||currentUser.role==='responsable';
const uid=()=>crypto.randomUUID();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const fmtDate=s=>new Date(s+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'});
const duration=(s,e)=>{if(!/^\d{2}:\d{2}$/.test(s)||!/^\d{2}:\d{2}$/.test(e))return 0;const a=s.split(':').map(Number),b=e.split(':').map(Number);return b[0]*60+b[1]-a[0]*60-a[1]};
const hours=m=>`${Math.floor(m/60)} h ${String(m%60).padStart(2,'0')}`;
const tutor=id=>data.tutors.find(t=>t.id===id)?.name||'Tuteur supprimé';
const group=id=>data.groups.find(g=>g.id===id)||{name:'Groupe supprimé',level:'—'};
const initials=n=>n.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
const person=id=>`<div class="person"><span class="avatar">${esc(initials(tutor(id)))}</span><div><strong>${esc(tutor(id))}</strong></div></div>`;
const badge=s=>`<span class="badge ${s==='Validée'?'valid':s==='À compléter'?'changes':s==='À vérifier'?'pending':'neutral'}">${esc(s)}</span>`;
function notify(m){$('#toast').textContent=m;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function validData(d){if(!d||d.version!==1||!['tutors','groups','tasks','entries'].every(k=>Array.isArray(d[k])&&d[k].length<100000))return false;const ids=a=>new Set(a.map(x=>x.id)).size===a.length;const str=(s,n=10000)=>typeof s==='string'&&s.length<=n;const date=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s+'T12:00:00'));const time=s=>/^([01]\d|2[0-3]):[0-5]\d$/.test(s);if(!['tutors','groups','tasks','entries'].every(k=>d[k].every(x=>x&&str(x.id,100))&&ids(d[k])))return false;if(!d.tutors.every(t=>str(t.name,100)&&t.name.trim())||!d.groups.every(g=>str(g.name,100)&&g.name.trim()&&str(g.level,100)&&g.level.trim()))return false;const refs=x=>d.tutors.some(t=>t.id===x.tutor)&&d.groups.some(g=>g.id===x.group);if(!d.tasks.every(t=>refs(t)&&str(t.title,250)&&date(t.due)))return false;return d.entries.every(e=>refs(e)&&date(e.date)&&time(e.start)&&time(e.end)&&duration(e.start,e.end)>0&&str(e.work,4000)&&str(e.result,2000)&&str(e.proof,3000)&&(!e.proof||/^https?:\/\//i.test(e.proof))&&['À vérifier','Validée','À compléter'].includes(e.status)&&Array.isArray(e.history)&&e.history.every(h=>str(h.at,100)&&str(h.note,2000)&&str(h.status,100))&&(!e.task||d.tasks.some(t=>t.id===e.task&&t.tutor===e.tutor&&t.group===e.group)))}
if(shared){data=window.RELAIS_BOOT.data}else{try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(validData(parsed))data=parsed}}catch{notify('Stockage indisponible.')}}
let saving=false;
async function commit(next){
 if(demo||!shared){try{localStorage.setItem(demo?DEMO:KEY,JSON.stringify(next));data=next;return true}catch{notify('Enregistrement impossible. Exportez vos données.');return false}}
 if(saving){notify('Un enregistrement est en cours.');return false}saving=true;document.body.classList.add('saving');
 try{const response=await fetch('/api/state',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({data:next,revision})});const result=await response.json();if(!response.ok){if(response.status===409){await refreshShared()}throw Error(result.error||'Enregistrement impossible.')}data=result.data;revision=result.revision;return true}catch(e){notify(e.message||'Connexion interrompue. Réessayez.');return false}finally{saving=false;document.body.classList.remove('saving')}
}
async function refreshShared(){const response=await fetch('/api/state');const result=await response.json();if(!response.ok)throw Error(result.error);data=result.data;revision=result.revision;currentUser=result.user;render()}
async function mutate(fn){const next=structuredClone(data);fn(next);if(!await commit(next))return false;render();return true}
function options(arr,label,selected=''){return `<option value="">${label}</option>`+arr.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.label||x.name)}</option>`).join('')}
function syncFilters(){const l=$('#level-filter').value,g=$('#group-filter').value;const levels=[...new Set(data.groups.map(g=>g.level))].sort();$('#level-filter').innerHTML=options(levels.map(x=>({id:x,name:x})),'Tous les niveaux',l);$('#group-filter').innerHTML=options(data.groups.filter(g=>!l||g.level===l),'Tous les groupes',g)}
function weekOf(date){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));const y=d.getUTCFullYear();return `${y}-W${String(Math.ceil((((d-new Date(Date.UTC(y,0,1)))/86400000)+1)/7)).padStart(2,'0')}`}
function matching(e){const g=group(e.group),q=$('#search').value.toLocaleLowerCase('fr');return(!$('#level-filter').value||g.level===$('#level-filter').value)&&(!$('#group-filter').value||e.group===$('#group-filter').value)&&(!$('#status-filter').value||e.status===$('#status-filter').value)&&(!$('#week-filter').value||weekOf(e.date)===$('#week-filter').value)&&(!q||[tutor(e.tutor),g.name,g.level,e.work,e.result].join(' ').toLocaleLowerCase('fr').includes(q))}
function filtered(){return data.entries.filter(matching).sort((a,b)=>(b.date+b.start).localeCompare(a.date+a.start))}
function empty(title,text,actions){return `<div class="empty"><div class="empty-symbol" aria-hidden="true">＋</div><h2>${title}</h2><p>${text}</p><div class="empty-actions">${actions}</div></div>`}
function render(){syncFilters();
if(shared){$('.local-label').textContent=currentUser.role==='responsable'?'Compte responsable · Données partagées':'Compte tuteur · '+currentUser.email;$('.aside-note').innerHTML='<span class="live-dot"></span> Sauvegarde partagée sur le serveur<p>Connecté : '+esc(currentUser.email)+'</p><button type="button" data-backup="yes">Télécharger une sauvegarde</button><a class="signout" href="/signout-with-chatgpt?return_to=/" target="_top">Se déconnecter</a>';$('#restore').hidden=!isAdmin();$('#backup').hidden=false;$('#restore').textContent='Restaurer JSON';$('nav button[data-view="team"]').hidden=!isAdmin();$('#new-entry').hidden=!isAdmin()&&view==='tasks';}
$('#demo-banner').hidden=!demo;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const rows=filtered(),minutes=rows.reduce((a,e)=>a+duration(e.start,e.end),0),valid=rows.filter(e=>e.status==='Validée');$('#stats').innerHTML=[['Temps déclaré',hours(minutes),'Sur la sélection affichée'],['Interventions',rows.length,`${new Set(rows.map(e=>e.tutor)).size} tuteur(s) concerné(s)`],['À vérifier',rows.filter(e=>e.status==='À vérifier').length,'En attente de contrôle'],['Temps validé',hours(valid.reduce((a,e)=>a+duration(e.start,e.end),0)),`${valid.length} intervention(s) validée(s)`]].map(([label,val,sub])=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${val}</div><small>${sub}</small></div>`).join('');$('#stats').hidden=view==='team';$('.toolbar').hidden=view==='team';$('#status-filter').hidden=view==='tasks';$('#new-entry').textContent=view==='tasks'?'+ Créer une tâche':view==='team'?'+ Ajouter à l’équipe':'+ Saisir une intervention';$('#page-title').textContent={journal:'Journal des interventions',tasks:'Tâches à réaliser',team:'Tuteurs & groupes'}[view];$('#page-description').textContent={journal:'Le temps consacré. Le travail accompli. Les actions à vérifier.',tasks:'Définissez le travail attendu, puis vérifiez sa réalisation.',team:'Organisez les tuteurs, les niveaux et les groupes.'}[view];$('#results').textContent=`${rows.length} intervention(s) · ${demo?'démonstration':'données de ce navigateur'}`;
if(view==='journal'){if(!data.entries.length&&!isAdmin()){$('#content').innerHTML=empty('Vos interventions apparaîtront ici','Saisissez votre première intervention pour indiquer le travail effectué et le temps consacré.','<button class="primary" data-action="entry">Saisir une intervention</button>');return}if(!data.entries.length){$('#content').innerHTML=empty('Votre suivi commence ici','Ajoutez vos tuteurs et vos groupes, puis enregistrez leur première intervention. Chaque saisie pourra ensuite être vérifiée.',`<button class="primary" data-action="team">Configurer mon équipe</button><button class="secondary" data-action="demo">Essayer la démonstration</button>`);return}if(!rows.length){$('#content').innerHTML=empty('Aucune intervention correspondante','Modifiez les filtres pour retrouver les interventions.',`<button class="secondary" data-action="reset">Réinitialiser les filtres</button>`);return}$('#content').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Tuteur / date</th><th>Niveau & groupe</th><th>Travail effectué</th><th>Temps</th><th>Vérification</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td>${person(e.tutor)}<div class="sub">${fmtDate(e.date)}</div></td><td>${esc(group(e.group).name)}<div class="sub">${esc(group(e.group).level)}</div></td><td><div class="work-title">${esc(e.work.length>140?e.work.slice(0,140)+'…':e.work)}</div>${e.proof?'<div class="sub">Justificatif lié</div>':''}</td><td class="duration">${hours(duration(e.start,e.end))}<div class="sub">${e.start} – ${e.end}</div></td><td>${badge(e.status)}</td><td><button class="row-action" data-detail="${esc(e.id)}">Examiner</button></td></tr>`).join('')}</tbody></table></div>`}
if(view==='tasks'){const q=$('#search').value.toLowerCase(),tasks=data.tasks.filter(t=>(!$('#level-filter').value||group(t.group).level===$('#level-filter').value)&&(!$('#group-filter').value||t.group===$('#group-filter').value)&&(!$('#week-filter').value||weekOf(t.due)===$('#week-filter').value)&&(!q||[t.title,tutor(t.tutor),group(t.group).name].join(' ').toLowerCase().includes(q))).sort((a,b)=>a.due.localeCompare(b.due));$('#results').textContent=`${tasks.length} tâche(s)`;$('#content').innerHTML=tasks.length?`<div class="table-wrap"><table><thead><tr><th>Travail attendu</th><th>Tuteur / groupe</th><th>Échéance</th><th>Réalisation</th><th></th></tr></thead><tbody>${tasks.map(t=>{const es=data.entries.filter(e=>e.task===t.id),status=es.some(e=>e.status==='Validée')?'Validée':es.some(e=>e.status==='À compléter')?'À compléter':es.length?'À vérifier':t.due<today()?'En retard':'À réaliser';return `<tr><td><div class="work-title">${esc(t.title)}</div></td><td>${esc(tutor(t.tutor))}<div class="sub">${esc(group(t.group).level)} · ${esc(group(t.group).name)}</div></td><td>${fmtDate(t.due)}</td><td>${badge(status)}<div class="sub">${es.length} intervention(s) liée(s)</div></td><td><button class="row-action" data-task-entry="${esc(t.id)}">${es.length?'Ajouter un suivi':'Saisir le travail'}</button></td></tr>`}).join('')}</tbody></table></div>`:empty('Un travail attendu, une échéance','Attribuez une tâche à un tuteur et à un groupe. Reliez ensuite ses interventions à cette tâche.',`<button class="primary" data-action="task">Créer une tâche</button>`)}
if(view==='team'){$('#results').textContent=`${data.tutors.length} tuteur(s) · ${data.groups.length} groupe(s)`;$('#content').innerHTML=`<div class="team-columns"><section><div class="team-heading"><h2>Tuteurs <span class="sub">(${data.tutors.length})</span></h2></div><div class="team-list">${data.tutors.map(t=>`<div class="team-item">${person(t.id)}<span class="sub">${esc(t.email||'Compte à renseigner')}<br>${data.entries.filter(e=>e.tutor===t.id).length} intervention(s)<br><button class="row-action" data-manage="${t.id}">Modifier / affecter</button>${window.RELAIS_PORTABLE?'<br><button class="row-action" data-account="'+esc(t.id)+'">Créer / réinitialiser l’accès</button>':''}</span></div>`).join('')||'<p>Aucun tuteur ajouté.</p>'}</div></section><section><div class="team-heading"><h2>Groupes <span class="sub">(${data.groups.length})</span></h2></div><div class="team-list">${data.groups.map(g=>`<div class="team-item"><strong>${esc(g.name)}</strong><span class="badge neutral">${esc(g.level)}</span></div>`).join('')||'<p>Aucun groupe ajouté.</p>'}</div></section></div><p class="sub" style="margin-top:28px">Les noms des niveaux et des groupes sont libres. Le groupe est précisé à chaque tâche et intervention.</p>`}}
function resetFilters(){$('#search').value='';['level-filter','group-filter','status-filter','week-filter'].forEach(id=>$('#'+id).value='');render()}
function fillForm(f){f.elements.tutor.innerHTML=options(data.tutors,'Choisir un tuteur');f.elements.group.innerHTML=options(data.groups.map(g=>({...g,label:g.level+' · '+g.name})),'Choisir un groupe');if(shared&&!isAdmin()){f.elements.tutor.value=currentUser.tutorId;f.elements.tutor.disabled=true}}
function tasksForForm(selected=''){const f=$('#entry-form');const allowed=data.tutors.find(t=>t.id===f.elements.tutor.value)?.groups;if(shared&&allowed){const current=f.elements.group.value;f.elements.group.innerHTML=options(data.groups.filter(g=>allowed.includes(g.id)).map(g=>({...g,label:g.level+' · '+g.name})),'Choisir un groupe',current)}f.elements.task.innerHTML=options(data.tasks.filter(t=>(!f.elements.tutor.value||t.tutor===f.elements.tutor.value)&&(!f.elements.group.value||t.group===f.elements.group.value)).map(t=>({id:t.id,name:t.title})),'Aucune tâche associée',selected)}
function manageTutor(id){const t=data.tutors.find(x=>x.id===id);if(!t||!isAdmin())return;const f=$('#setup-form');f.reset();f.elements.editId.value=id;f.elements.type.value='tutor';f.elements.type.disabled=true;f.elements.name.value=t.name;f.elements.email.value=t.email||'';f.elements.email.required=true;$('#account-fields').hidden=false;$('#level-label').hidden=true;f.elements.level.required=false;$('#assigned-groups').innerHTML=data.groups.map(g=>'<option value="'+esc(g.id)+'" '+((t.groups||[]).includes(g.id)?'selected':'')+'>'+esc(g.level+' · '+g.name)+'</option>').join('');$('#setup-error').textContent='';$('#setup-dialog').showModal()}
function ready(){if(!data.tutors.length||!data.groups.length){if(shared&&!isAdmin()){notify('Aucun groupe ne vous est affecté. Contactez le responsable.');return false}view='team';render();notify('Ajoutez au moins un tuteur et un groupe.');return false}return true}
function openEntry(id='',taskId=''){if(!ready())return;const f=$('#entry-form');f.reset();fillForm(f);$('#entry-error').textContent='';f.elements.id.value='';f.elements.date.value=today();$('#entry-title').textContent=id?'Modifier l’intervention':'Nouvelle intervention';if(id){const e=data.entries.find(x=>x.id===id);for(const k of ['id','tutor','group','date','start','end','work','result','proof'])f.elements[k].value=e[k];tasksForForm(e.task)}else{const t=data.tasks.find(t=>t.id===taskId);if(t){f.elements.tutor.value=t.tutor;f.elements.group.value=t.group}tasksForForm(taskId)}calc();$('#entry-dialog').showModal()}
function calc(){const f=$('#entry-form'),m=duration(f.elements.start.value,f.elements.end.value);$('#calculated').textContent=m>0?hours(m):'—'}
function openTask(){if(!ready())return;const f=$('#task-form');f.reset();fillForm(f);f.elements.due.value=today();$('#task-dialog').showModal()}
function safeLink(url){try{const u=new URL(url);return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}}
function detail(id){const e=data.entries.find(x=>x.id===id);if(!e)return;const t=data.tasks.find(t=>t.id===e.task),link=safeLink(e.proof);$('#detail-content').innerHTML=`<div class="dialog-head"><div><h2>Vérifier l’intervention</h2><p>${esc(tutor(e.tutor))} · ${fmtDate(e.date)}</p></div><button type="button" class="close" data-close="detail-dialog" aria-label="Fermer">×</button></div><div class="detail-meta">${badge(e.status)}<span>${esc(group(e.group).level)} · ${esc(group(e.group).name)}</span><strong>${hours(duration(e.start,e.end))}</strong><span>${e.start} – ${e.end}</span></div>${t?`<div class="detail-section"><h3>Tâche associée</h3><p>${esc(t.title)}</p></div>`:''}<div class="detail-section"><h3>Travail effectué</h3><p>${esc(e.work)}</p></div><div class="detail-section"><h3>Résultat / suite à donner</h3><p>${esc(e.result||'Aucun complément renseigné.')}</p></div><div class="detail-section"><h3>Justificatif</h3>${link?`<a href="${esc(link)}" target="_blank" rel="noopener noreferrer">Ouvrir le justificatif</a>`:'<p>Aucun lien fourni.</p>'}</div><div class="detail-section"><h3>Historique</h3>${e.history.map(h=>`<p><strong>${esc(h.status)}</strong> · ${esc(new Date(h.at).toLocaleString('fr-FR'))}${h.note?'<br>'+esc(h.note):''}</p>`).join('')}</div><div class="detail-section"><h3>Contrôle du responsable</h3><p class="sub">Le responsable vérifie le travail et conserve une observation datée.</p><label>Observation<textarea class="review-note" id="review-note" maxlength="2000" rows="2" placeholder="Précisez le contrôle effectué ou le complément attendu."></textarea></label><div class="review-actions"><button class="primary" data-review="Validée" data-id="${e.id}">Valider le travail</button><button class="secondary" data-review="À compléter" data-id="${e.id}">Demander un complément</button><button class="secondary" data-edit="${e.id}">Modifier la saisie</button><button class="danger" data-delete="${e.id}">Supprimer</button></div></div>`;if(shared&&!isAdmin()){$('[data-review],[data-delete]').forEach(b=>b.hidden=true);$('#review-note').closest('label').hidden=true}if(!$('#detail-dialog').open)$('#detail-dialog').showModal()}
$('#entry-form').addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target,v=Object.fromEntries(new FormData(f));if(shared&&!isAdmin())v.tutor=currentUser.tutorId;const m=duration(v.start,v.end);if(m<=0){$('#entry-error').textContent='L’heure de fin doit être après l’heure de début, le même jour.';return}if(v.date>today()){$('#entry-error').textContent='Une intervention réalisée ne peut pas être datée dans le futur.';return}if(!v.work.trim()){$('#entry-error').textContent='Décrivez le travail effectué.';return}if(v.proof&&!safeLink(v.proof)){$('#entry-error').textContent='Le justificatif doit être un lien HTTP ou HTTPS.';return}const overlap=data.entries.some(e=>e.id!==v.id&&e.tutor===v.tutor&&e.date===v.date&&e.start<v.end&&e.end>v.start);if(overlap){$('#entry-error').textContent='Ce tuteur a déjà une intervention sur ce créneau. Vérifiez les horaires.';return}const old=data.entries.find(e=>e.id===v.id);const entry={...v,id:v.id||uid(),work:v.work.trim(),result:v.result.trim(),status:'À vérifier',history:[...(old?.history||[]),{at:new Date().toISOString(),status:old?'Saisie modifiée — à vérifier':'Intervention enregistrée',note:''}]};if(await mutate(d=>{const i=d.entries.findIndex(e=>e.id===entry.id);if(i<0)d.entries.push(entry);else d.entries[i]=entry})){$('#entry-dialog').close();notify('Intervention enregistrée. Elle est à vérifier.')}});
$('#task-form').addEventListener('submit',async ev=>{ev.preventDefault();const v=Object.fromEntries(new FormData(ev.target));v.title=v.title.trim();if(!v.title)return;if(await mutate(d=>d.tasks.push({...v,id:uid()}))){$('#task-dialog').close();notify('Tâche créée.')}});
$('#setup-form').elements.type.addEventListener('change',e=>{$('#level-label').hidden=e.target.value!=='group';$('#setup-form').elements.level.required=e.target.value==='group';$('#account-fields').hidden=e.target.value==='group';$('#setup-form').elements.email.required=e.target.value==='tutor'});
$('#setup-form').addEventListener('submit',async ev=>{ev.preventDefault();const v=Object.fromEntries(new FormData(ev.target));if(v.editId)v.type='tutor';v.name=v.name.trim();v.level=v.level.trim();const arr=v.type==='tutor'?data.tutors:data.groups;if(v.type==='tutor'){v.email=v.email.trim().toLowerCase();if(!v.email){$('#setup-error').textContent='Indiquez l’adresse e-mail du compte du tuteur.';return}}if(!v.name||(v.type==='group'&&!v.level)){return}if(arr.some(x=>x.id!==v.editId&&x.name.toLowerCase()===v.name.toLowerCase()&&(v.type==='tutor'||x.level.toLowerCase()===v.level.toLowerCase()))){$('#setup-error').textContent='Ce nom existe déjà.';return}if(await mutate(d=>{if(v.type==='tutor'){const item={id:v.editId||uid(),name:v.name,email:v.email,groups:[...$('#assigned-groups').selectedOptions].map(o=>o.value)};const index=d.tutors.findIndex(t=>t.id===item.id);if(index>=0)d.tutors[index]=item;else d.tutors.push(item)}else d.groups.push({id:uid(),name:v.name,level:v.level})})){$('#setup-dialog').close();notify(v.type==='tutor'?'Tuteur ajouté.':'Groupe ajouté.')}});
$('#new-entry').onclick=()=>{if(view==='journal')openEntry();else if(view==='tasks')openTask();else{const f=$('#setup-form');f.reset();f.elements.editId.value='';f.elements.type.disabled=false;f.elements.level.required=false;f.elements.email.required=true;$('#account-fields').hidden=false;$('#assigned-groups').innerHTML=data.groups.map(g=>'<option value="'+esc(g.id)+'">'+esc(g.level+' · '+g.name)+'</option>').join('');$('#level-label').hidden=true;$('#setup-error').textContent='';$('#setup-dialog').showModal()}};
$$('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
['search','level-filter','group-filter','status-filter','week-filter'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{if(id==='level-filter')$('#group-filter').value='';render()}));$('#reset-filters').onclick=resetFilters;
['start','end'].forEach(n=>$('#entry-form').elements[n].addEventListener('input',calc));['tutor','group'].forEach(n=>$('#entry-form').elements[n].addEventListener('change',()=>tasksForForm()));
$('#start-now').onclick=()=>{const d=new Date();$('#entry-form').elements.start.value=`${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;calc()};
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.manage)manageTutor(b.dataset.manage);if(b.dataset.account){const t=data.tutors.find(t=>t.id===b.dataset.account);$('#account-form').reset();$('#account-form').elements.email.value=t.email;$('#account-name').textContent=t.name;$('#account-error').textContent='';$('#account-dialog').showModal()}if(b.dataset.backup)$('#backup').click();if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.taskEntry)openEntry('',b.dataset.taskEntry);if(b.dataset.edit){$('#detail-dialog').close();openEntry(b.dataset.edit)}if(b.dataset.delete&&isAdmin()&&confirm('Supprimer définitivement cette intervention ?')){if(await mutate(d=>d.entries=d.entries.filter(e=>e.id!==b.dataset.delete))){$('#detail-dialog').close();notify('Intervention supprimée.')}}if(b.dataset.review){if(!isAdmin()){notify('La validation est réservée au responsable.');return}const note=$('#review-note').value.trim();if(!note){notify('Ajoutez une observation pour garder une trace du contrôle.');$('#review-note').focus();return}if(await mutate(d=>{const e=d.entries.find(x=>x.id===b.dataset.id);e.status=b.dataset.review;e.history.push({at:new Date().toISOString(),status:b.dataset.review,note})})){detail(b.dataset.id);notify('Vérification enregistrée.')}}if(b.dataset.action==='team'&&isAdmin()){view='team';render()}if(b.dataset.action==='reset')resetFilters();if(b.dataset.action==='task')openTask();if(b.dataset.action==='entry')openEntry();if(b.dataset.action==='demo')loadDemo()});
function download(content,type,name){const blob=new Blob([content],{type}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#backup').onclick=()=>{download(JSON.stringify(data,null,2),'application/json',`relais-${demo?'demo-':''}${today()}.json`);notify('Sauvegarde téléchargée.')};
$('#restore').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error();const d=JSON.parse(await f.text());if(!validData(d))throw Error();if(confirm(`Remplacer les données ${demo?'de démonstration':'de ce navigateur'} par cette sauvegarde (${d.entries.length} interventions) ?`)){if(await commit(d)){resetFilters();notify('Sauvegarde restaurée.')}}}catch{notify('Fichier invalide. Choisissez une sauvegarde JSON exportée par Relais.')}ev.target.value=''};
function csvCell(s){let v=String(s??'');if(/^[\s]*[=+\-@]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}
$('#export-csv').onclick=()=>{const tasks=view==='tasks';const rows=tasks?data.tasks.filter(t=>(!$('#level-filter').value||group(t.group).level===$('#level-filter').value)&&(!$('#group-filter').value||t.group===$('#group-filter').value)&&(!$('#week-filter').value||weekOf(t.due)===$('#week-filter').value)&&(!$('#search').value||[t.title,tutor(t.tutor),group(t.group).name].join(' ').toLowerCase().includes($('#search').value.toLowerCase()))).map(t=>[t.title,tutor(t.tutor),group(t.group).level,group(t.group).name,t.due,data.entries.filter(e=>e.task===t.id).length]):filtered().map(e=>[e.date,tutor(e.tutor),group(e.group).level,group(e.group).name,e.start,e.end,duration(e.start,e.end),e.work,e.result,e.status,e.proof]);const headings=tasks?['Travail attendu','Tuteur','Niveau','Groupe','Échéance','Interventions liées']:['Date','Tuteur','Niveau','Groupe','Début','Fin','Durée (minutes)','Travail effectué','Résultat','Statut','Justificatif'];download('\uFEFF'+[headings,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8',`relais-${tasks?'taches':'interventions'}-${today()}.csv`)};
function loadDemo(){if(shared&&!isAdmin())return;demo=true;const d=fresh();d.tutors=[{id:'t1',name:'Aminata Diallo',email:'aminata@example.org',groups:['g1']},{id:'t2',name:'Marc Kouamé',email:'marc@example.org',groups:['g2']},{id:'t3',name:'Fatou Ndiaye',email:'fatou@example.org',groups:['g3']}];d.groups=[{id:'g1',name:'Groupe A',level:'Niveau 1'},{id:'g2',name:'Groupe B',level:'Niveau 2'},{id:'g3',name:'Groupe C',level:'Niveau 1'}];d.tasks=[{id:'k1',title:'Corriger les travaux de la semaine',tutor:'t1',group:'g1',due:today()},{id:'k2',title:'Préparer les supports de la prochaine séance',tutor:'t2',group:'g2',due:today()},{id:'k3',title:'Animer la séance de révision',tutor:'t3',group:'g3',due:today()}];d.entries=[{tutor:'t1',group:'g1',start:'09:00',end:'10:30',work:'Correction des travaux et rédaction des retours pour le groupe.',result:'Travaux corrigés. Retours préparés pour la prochaine séance.',status:'À vérifier',task:'k1'},{tutor:'t2',group:'g2',start:'10:00',end:'11:00',work:'Préparation des supports et des exercices de la prochaine séance.',result:'Support finalisé et vérifié par le responsable.',status:'Validée',task:'k2'},{tutor:'t3',group:'g3',start:'14:00',end:'15:15',work:'Animation de la séance de révision des notions de la semaine.',result:'Séance réalisée. Compte rendu à compléter.',status:'À compléter',task:'k3'}].map(e=>({...e,id:uid(),date:today(),proof:'',history:[{at:new Date().toISOString(),status:e.status,note:'Exemple fictif pour la démonstration.'}]}));try{const saved=localStorage.getItem(DEMO);if(saved&&validData(JSON.parse(saved)))data=JSON.parse(saved);else data=d}catch{data=d}view='journal';resetFilters();notify('Démonstration : vos données réelles restent séparées.')}
$('#exit-demo').onclick=()=>{demo=false;if(shared){data=window.RELAIS_BOOT.data;refreshShared().catch(e=>notify(e.message))}else{try{const d=JSON.parse(localStorage.getItem(KEY));data=validData(d)?d:fresh()}catch{data=fresh()}}resetFilters();notify('Retour à vos données.')};
$('#today').textContent=new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});render();

$('#account-form').addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target,b=f.querySelector('button[type=submit]');b.disabled=true;try{const response=await fetch('/auth/accounts',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const result=await response.json();if(!response.ok)throw Error(result.error);f.elements.password.value='';$('#account-dialog').close();notify('Accès enregistré. Communiquez le mot de passe au tuteur.')}catch(e){$('#account-error').textContent=e.message||'Connexion interrompue.'}finally{b.disabled=false}});
